use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

const MAX_QUESTION_LEN: usize = 512;
const MAX_LOOKUP_QUERY_LEN: usize = 512;
const MAX_PROMPT_LEN: usize = 16 * 1024;
const MAX_ROUNDS: usize = 4;

const SYSTEM: &str = "You answer customer support questions. If you need more \
information, call the tool `lookup` with a short query to search the knowledge \
base. Otherwise answer the question directly and concisely.";

struct Node;

/// Append to the prompt, refusing to grow it past the budget.
fn push(prompt: &mut String, s: &str) -> Result<(), String> {
    if prompt.len() + s.len() > MAX_PROMPT_LEN {
        return Err("prompt exceeds budget".into());
    }
    prompt.push_str(s);
    Ok(())
}

fn answer(ctx: &ConversationContext) -> Result<String, String> {
    if ctx.question.len() > MAX_QUESTION_LEN {
        return Err("question exceeds 512 bytes".into());
    }

    let mut prompt = String::new();
    push(
        &mut prompt,
        &format!("Intent: {:?}\nQuestion: {}\n", ctx.intent, ctx.question),
    )?;
    if !ctx.knowledge.is_empty() {
        push(&mut prompt, "Context:\n")?;
        for k in &ctx.knowledge {
            push(&mut prompt, "- ")?;
            push(&mut prompt, k)?;
            push(&mut prompt, "\n")?;
        }
    }

    for _ in 0..MAX_ROUNDS {
        match tool_llm::generate(SYSTEM, &prompt) {
            Reply::Text(text) => return Ok(text),
            Reply::Call(req) => {
                // Only the granted tool is served; anything else ends the run.
                if req.tool != "lookup" {
                    return Err("model requested an unavailable tool".into());
                }
                if req.query.len() > MAX_LOOKUP_QUERY_LEN {
                    return Err("lookup query exceeds 512 bytes".into());
                }

                let hits = kb_read::lookup(&req.query);

                push(&mut prompt, "\nLookup results for ")?;
                push(&mut prompt, &req.query)?;
                push(&mut prompt, ":\n")?;
                if hits.is_empty() {
                    push(&mut prompt, "(none)\n")?;
                }
                for h in &hits {
                    push(&mut prompt, "- ")?;
                    push(&mut prompt, h)?;
                    push(&mut prompt, "\n")?;
                }
            }
        }
    }

    Err("tool-call budget exhausted".into())
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        match answer(&ctx) {
            Ok(text) => ResponseResult::Ok(AgentResponse { text }),
            Err(message) => ResponseResult::Error(LlmError { message }),
        }
    }
}

export!(Node);
